2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	  enchantment?: number;
9	}
10	
11	const PROCESSING_FEE = 5;
12	const CURSE_SURCHARGE_RATE = 0.5;
13	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
14	const HIGH_ENCHANTMENT_LEVEL = 5;
15	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
16	const LOYALTY_DISCOUNT_RATE = 0.2;
17	const LOYALTY_YEARS = 2;
18	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
19	
20	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	};
26	
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	const COMPONENT_BASE_PREMIUM = 25;
29	const BLOCK_SIZE = 3;
30	const BLOCK_BASE_PREMIUM = 60;
31	
32	function isComponent(item: Item): boolean {
33	  return COMPONENT_TYPES.has(item.type);
34	}
35	
36	function alikeComponentGroupSizes(components: Item[]): number[] {
37	  const sizePerType = new Map<string, number>();
38	  for (const component of components) {
39	    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
40	  }
41	  return [...sizePerType.values()];
42	}
43	
44	function alikeComponentGroupBasePremium(groupSize: number): number {
45	  return groupSize === BLOCK_SIZE
46	    ? BLOCK_BASE_PREMIUM
47	    : groupSize * COMPONENT_BASE_PREMIUM;
48	}
49	
50	function componentsBasePremium(components: Item[]): number {
51	  return alikeComponentGroupSizes(components)
52	    .map(alikeComponentGroupBasePremium)
53	    .reduce((sum, premium) => sum + premium, 0);
54	}
55	
56	function mainItemsBasePremium(mainItems: Item[]): number {
57	  return mainItems
58	    .map((mainItem) => MAIN_ITEM_BASE_PREMIUMS[mainItem.type])
59	    .reduce((sum, premium) => sum + premium, 0);
60	}
61	
62	function policyBasePremium(items: Item[]): number {
63	  return (
64	    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
65	    componentsBasePremium(items.filter(isComponent))
66	  );
67	}
68	
69	function surchargeableItemBasePremium(item: Item): number {
70	  return isComponent(item)
71	    ? COMPONENT_BASE_PREMIUM
72	    : MAIN_ITEM_BASE_PREMIUMS[item.type];
73	}
74	
75	interface ItemRisk {
76	  applies: (item: Item) => boolean;
77	  surchargeRate: number;
78	}
79	
80	const isCursed = (item: Item): boolean => item.cursed === true;
81	
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
84	
85	const ITEM_RISKS: ItemRisk[] = [
86	  { applies: isCursed, surchargeRate: CURSE_SURCHARGE_RATE },
87	  { applies: isHighlyEnchanted, surchargeRate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
88	];
89	
90	function itemRiskSurcharge(item: Item): number {
91	  return ITEM_RISKS.filter((risk) => risk.applies(item))
92	    .map((risk) => surchargeableItemBasePremium(item) * risk.surchargeRate)
93	    .reduce((sum, surcharge) => sum + surcharge, 0);
94	}
95	
96	function itemRiskSurcharges(items: Item[]): number {
97	  return items
98	    .map(itemRiskSurcharge)
99	    .reduce((sum, surcharge) => sum + surcharge, 0);
100	}
