102	// Every item in a quote is insured for the first time, so the initial assessment
103	// surcharge applies to every quote -- it does not depend on the customer's history.
104	function initialAssessmentOnEveryQuote(basePremium: number): number {
105	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
106	}
107	
108	interface CustomerStanding {
109	  yearsWithMHPCO: number;
110	  previousContracts: number;
111	}
112	
113	interface CustomerStandingDiscount {
114	  earnedBy: (standing: CustomerStanding) => boolean;
115	  discountRate: number;
116	}
117	
118	const isLongStanding = (standing: CustomerStanding): boolean =>
119	  standing.yearsWithMHPCO >= LOYALTY_YEARS;
120	
121	const isFollowUpContract = (standing: CustomerStanding): boolean =>
122	  standing.previousContracts > 0;
123	
124	const CUSTOMER_STANDING_DISCOUNTS: CustomerStandingDiscount[] = [
125	  { earnedBy: isLongStanding, discountRate: LOYALTY_DISCOUNT_RATE },
126	  { earnedBy: isFollowUpContract, discountRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
127	];
128	
129	function customerStandingDiscounts(
130	  standing: CustomerStanding,
131	  basePremium: number,
132	): number {
133	  return CUSTOMER_STANDING_DISCOUNTS.filter((discount) =>
134	    discount.earnedBy(standing),
135	  )
136	    .map((discount) => basePremium * discount.discountRate)
137	    .reduce((sum, amount) => sum + amount, 0);
138	}
139	
140	function policyWideModifiers(
141	  standing: CustomerStanding,
142	  basePremium: number,
143	): number {
144	  return (
145	    initialAssessmentOnEveryQuote(basePremium) -
146	    customerStandingDiscounts(standing, basePremium)
147	  );
148	}
149	
150	function premiumRoundedInMhpcosFavor(premium: number): number {
151	  return Math.ceil(premium);
152	}
153	
154	export function quote(
155	  customer: Customer,
156	  items: Item[],
157	  previousContracts: number,
158	): number {
159	  const basePremium = policyBasePremium(items);
160	  const standing = { ...customer, previousContracts };
161	  const premium =
162	    basePremium +
163	    itemRiskSurcharges(items) +
164	    policyWideModifiers(standing, basePremium) +
165	    PROCESSING_FEE;
166	  return premiumRoundedInMhpcosFavor(premium);
167	}
